```python
if Version(jax.__version__) >= Version("0.10.0"):
    from jax.scipy.linalg import qr_update
else:
    @functool.partial(jit, static_argnames="mode")
    def qr_update(A, b, mode="right"):
        Q, R = qr(A, mode="economic")
        if mode == "right":
            return Q.T@b, R
        elif mode == "left":
            return b.T@Q
        else:
            raise NotImplementedError()
```
